    private void fieldCalcularActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_fieldCalcularActionPerformed
        String titular;
        Consumidor consumidor;
        String tipoConsumidor;
        int kWhMes;
        
        titular = fieldTitular.getText();
        kWhMes = Integer.parseInt(fieldkWhMes.getText());
        tipoConsumidor = fieldConsumidor.getText();
        
        if ("RESIDENCIAL".equals(tipoConsumidor)){
            consumidor = Consumidor.RESIDENCIAL;
        } else if ("COMERCIAL".equals(tipoConsumidor)){
            consumidor = Consumidor.COMERCIAL;
        } else if ("INDUSTRIAL".equals(tipoConsumidor)){
            consumidor = Consumidor.INDUSTRIAL;
        } else {
            consumidor = null;
        }
         
        FaturaEletrica faturaEletrica = new FaturaEletrica(titular, consumidor, kWhMes);
        double fatura = faturaEletrica.calcularFatura();
        
        fieldFatura.setText("Fatura: "+fatura);
        
    }//GEN-LAST:event_fieldCalcularActionPerformed

